'use strict';
// Synthetic, isolated service wallets. No RPC, signing, secrets or real transactions.
const ownRoutes=[
 {id:'OW-USDT-TRON',asset:'USDT',network:'TRON · TRC-20',address:'T'+ 'B'.repeat(33),gas:'TRX',fee:5,gasBalance:100},
 {id:'OW-USDT-ETH',asset:'USDT',network:'Ethereum · ERC-20',address:'0x'+'3'.repeat(40),gas:'ETH',fee:0.0002,gasBalance:1},
 {id:'OW-USDC-ETH',asset:'USDC',network:'Ethereum · ERC-20',address:'0x'+'6'.repeat(40),gas:'ETH',fee:0.0002,gasBalance:1}
];
const ownStates={draft:['Черновик','Draft'],review:['Проверено · нужны подтверждения','Reviewed · approvals needed'],waiting:['Ожидает второго владельца','Awaiting second owner'],approved:['Два владельца подтвердили','Two owners approved'],unknown:['Результат неизвестен · повтор запрещён','Unknown outcome · do not resend'],confirmed:['Перевод подтверждён','Transfer confirmed'],failed:['Окончательный отказ подтверждён','Final failure confirmed'],cancelled:['Отменено до отправки','Cancelled before submission']};
function ownState(){return finance.own??=( {screen:'form',source:ownRoutes[0].id,address:'',amount:'',reason:'',ack:false,current:null,records:[],floors:Object.fromEntries(ownRoutes.map(s=>[s.id,{value:100000000,version:1}])),floorDraft:null,block:'none',outcome:'unknown',notice:null} );}
const ownSource=()=>ownRoutes.find(s=>s.id===ownState().source);
const ownCurrent=()=>ownState().records.find(x=>x.id===ownState().current);
const ownMicros=v=>/^\d{1,9}(\.\d{1,6})?$/.test(String(v))&&Number(v)<=1000000?Math.round(Number(v)*1e6):null;
const ownMoney=(v,asset)=>new Intl.NumberFormat(state.locale==='ru'?'ru-RU':'en-US',{maximumFractionDigits:6}).format(v/1e6)+' '+asset;
function ownActorValid(id){const a=accountFixtures.find(x=>x.id===id),g=management.assignments[id];return !!a?.owner&&!!g&&g.status==='active'&&(!g.expires||g.expires>management.clock)&&!management.revoked;}
const ownWrite=()=>financeAccess().write&&ownActorValid(actor().id);
const ownBlocked=()=>technicalLocked()||finance.block!=='none'||ownState().block!=='none';
const ownTerminal=p=>['confirmed','failed','cancelled'].includes(p.status);
function ownFunds(id,exclude){const x=ownState();const settled=x.records.filter(p=>p.source===id&&p.status==='confirmed').reduce((n,p)=>n+p.units,0),held=x.records.filter(p=>p.source===id&&p.id!==exclude&&!ownTerminal(p)&&p.status!=='draft').reduce((n,p)=>n+p.units,0);return {balance:1000000000+(typeof depositCredited==='function'?depositCredited(id):0)-settled,obligations:200000000,reserves:50000000,floor:x.floors[id].value,held,available:Math.max(0,1000000000+(typeof depositCredited==='function'?depositCredited(id):0)-settled-200000000-50000000-x.floors[id].value-held)};}
function ownGasFree(id,exclude){const s=ownRoutes.find(s=>s.id===id);return s.gasBalance-ownState().records.filter(p=>p.source===id&&p.id!==exclude&&!['failed','cancelled','draft'].includes(p.status)).reduce((n,p)=>n+p.fee,0);}
const ownDigest=p=>JSON.stringify([p.id,p.version,p.source,p.address,p.units,p.reason,p.fee,p.floorVersion]);
function ownApprovals(p){return p.approvals.filter((a,i,all)=>a.digest===ownDigest(p)&&a.expires>Date.now()&&ownActorValid(a.id)&&a.grantRevision===management.assignments[a.id].revision&&all.findIndex(b=>b.id===a.id)===i);}
const ownDisplayApprovals=p=>p.status==='unknown'||ownTerminal(p)?p.approvals:ownApprovals(p);
function ownError(ru,en){ownState().notice=[ru,en];return false;}
function ownValidAddress(s,address){return s.gas==='TRX'?/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(address):/^0x[0-9a-fA-F]{40}$/.test(address)&&!/^0x0{40}$/.test(address);}
function ownReview(){const x=ownState(),s=ownSource(),units=ownMicros(x.amount);if(!ownWrite()||ownBlocked())return ownError('Вывод запрещён: проверьте права и ограничения.','Withdrawal blocked: check permissions and restrictions.');if(x.records.some(p=>!ownTerminal(p)&&p.status!=='draft'&&p.id!==x.current))return ownError('Сначала завершите текущую операцию или её сверку.','Complete the pending operation or its reconciliation first.');if(!s||!ownValidAddress(s,x.address.trim())||x.address.trim().toLowerCase()===s.address.toLowerCase())return ownError('Укажите полный адрес получателя в выбранной сети, отличный от источника.','Enter a complete recipient address in the selected network, different from the source.');if(!units||units>ownFunds(s.id,x.current).available||ownGasFree(s.id,x.current)<s.fee)return ownError('Недостаточно свободных средств или валюты для комиссии сети.','Insufficient available funds or network fee currency.');if(x.reason.trim().length<8||!x.ack)return ownError('Укажите назначение от 8 символов и подтвердите проверку сети и адреса.','Provide a purpose of at least 8 characters and confirm the network and address.');let p=ownCurrent();if(p&&p.status!=='draft')return false;if(!p){p={id:'WD-DEMO-'+(x.records.length+1),version:0,approvals:[]};x.records.push(p);x.current=p.id;}Object.assign(p,{source:s.id,address:x.address.trim(),units,reason:x.reason.trim(),fee:s.fee,floorVersion:x.floors[s.id].version,status:'review',approvals:[],version:p.version+1,external:null});finance.proof=null;x.screen='review';x.notice=null;return true;}
function ownReady(p){return ownWrite()&&!ownBlocked()&&p&&['review','waiting','approved'].includes(p.status)&&p.floorVersion===ownState().floors[p.source].version&&p.units<=ownFunds(p.source,p.id).available&&ownGasFree(p.source,p.id)>=p.fee;}
function ownAction(action){const x=ownState(),p=ownCurrent();x.notice=null;if(!financeAccess().read)return false;
 if(action==='open'){finance.view='own';if(p?.status==='unknown')x.screen='review';navigate('finance');return true;}
 if(action==='review')return ownReview();
 if(action==='settings'){x.screen='settings';return true;}
 if(action==='back'){x.screen=p&&!ownTerminal(p)&&p.status!=='draft'?'review':'form';if(p?.status==='draft')Object.assign(x,{source:p.source,address:p.address,amount:String(p.units/1e6),reason:p.reason,ack:false});return true;}
 if(action==='handoff'){finance.proof=null;financeAction('handoff');return true;}
 if(action==='proof'){if(!ownReady(p)||!account.protected)return ownError('Нужны действующие права, защищённый вход и актуальная проверка операции.','Current rights, protected sign-in and an up-to-date operation review are required.');finance.proof={id:actor().id,grantRevision:management.assignments[actor().id].revision,digest:ownDigest(p),expires:Date.now()+300000};x.notice=['Личность подтверждена в учебном примере. Теперь подтвердите действие.','Identity verified in this example. Now approve the action.'];return true;}
 if(action==='approve'){if(!ownReady(p)||finance.proof?.id!==actor().id||finance.proof.digest!==ownDigest(p)||finance.proof.expires<Date.now()||finance.proof.grantRevision!==management.assignments[actor().id].revision||ownApprovals(p).some(a=>a.id===actor().id))return ownError('Подтверждение не принято: проверьте личность. Каждый владелец подтверждает один раз.','Approval rejected: verify identity. Each owner approves once.');p.approvals=ownApprovals(p);p.approvals.push({...finance.proof});finance.proof=null;p.status=p.approvals.length===2?'approved':'waiting';return true;}
 if(action==='send'){if(!ownReady(p)||ownApprovals(p).length!==2||p.status!=='approved')return ownError('Отправка запрещена. Нужны два действующих подтверждения этой версии и свободные средства.','Submission blocked. Two current approvals for this version and available funds are required.');p.status='unknown';p.submittedAt=new Date().toISOString();p.reference='SEND-DEMO-'+p.id;finance.proof=null;flog('Отправлен учебный вывод '+p.id,'Synthetic withdrawal submitted '+p.id);return true;}
 if(action==='reconcile'){if(!ownWrite()||p?.status!=='unknown')return false;if(x.outcome==='success'){p.status='confirmed';p.external='TX-DEMO-'+p.id;}else if(x.outcome==='failure'){p.status='failed';p.external='FINAL-FAILURE-DEMO-'+p.id;}else return ownError('Подтверждения нет. Резерв сохранён, повторная отправка запрещена.','No evidence. Reserve remains; resubmission is blocked.');flog('Сверка исходного вывода '+p.id,'Original withdrawal reconciled '+p.id);return true;}
 if(action==='edit'||action==='cancel'){if(!ownWrite()||!p||!['review','waiting','approved'].includes(p.status))return false;if(action==='edit')Object.assign(x,{source:p.source,address:p.address,amount:String(p.units/1e6),reason:p.reason});p.status=action==='edit'?'draft':'cancelled';p.approvals=[];finance.proof=null;x.ack=false;x.screen='form';if(action==='cancel')x.current=null;return true;}
 if(action==='new'){if(x.records.some(p=>!ownTerminal(p)))return ownError('Сначала завершите текущую операцию.','Complete the current operation first.');Object.assign(x,{current:null,address:'',amount:'',reason:'',ack:false,screen:'form'});return true;}
 if(action==='floor-review'){if(!ownWrite()||ownBlocked())return false;const units=ownMicros(x.floorInput??''),reason=x.floorReason??'';if(units===null||reason.trim().length<8)return ownError('Укажите остаток от 0 и причину от 8 символов.','Enter a non-negative floor and a reason of at least 8 characters.');x.floorDraft={source:x.source,units,reason,version:x.floors[x.source].version+1,approvals:[]};finance.proof=null;return true;}
 if(action==='floor-proof'){if(!ownWrite()||ownBlocked()||!account.protected||!x.floorDraft)return false;finance.proof={id:actor().id,grantRevision:management.assignments[actor().id].revision,digest:JSON.stringify(x.floorDraft),expires:Date.now()+300000};x.notice=['Личность подтверждена в учебном примере. Теперь подтвердите действие.','Identity verified in this example. Now approve the action.'];return true;}
 if(action==='floor-approve'){const d=x.floorDraft;if(!ownWrite()||ownBlocked()||!d||finance.proof?.id!==actor().id||finance.proof.digest!==JSON.stringify(d)||finance.proof.expires<Date.now()||finance.proof.grantRevision!==management.assignments[actor().id].revision||d.approvals.includes(actor().id))return ownError('Сначала подтвердите личность; нужны два разных владельца.','Verify identity first; two different owners are required.');d.approvals=d.approvals.filter(ownActorValid);d.approvals.push(actor().id);finance.proof=null;if(d.approvals.length===2){x.floors[d.source]={value:d.units,version:d.version};for(const op of x.records.filter(p=>p.source===d.source&&['review','waiting','approved'].includes(p.status))){op.approvals=[];op.status='draft';}x.floorDraft=null;x.notice=['Минимальный остаток изменён. Незавершённый вывод нужно проверить заново.','Minimum balance updated. Review any unsubmitted withdrawal again.'];flog('Обновлён минимальный остаток '+d.source,'Minimum balance updated '+d.source);}return true;}
 return false;
}
const ownButton=(ru,en,a,primary=false,disabled=false)=>`<button type="button" class="btn${primary?' primary':''}" data-own="${a}" ${disabled?'disabled':''}>${pl(ru,en)}</button>`;
function ownInput(id,ru,en,value,type='text'){return `<div class="field"><label for="own-${id}">${pl(ru,en)}</label><input id="own-${id}" data-own-field="${id}" type="${type}" value="${escape(value||'')}" ${type==='number'?'min="0" step="0.000001" max="1000000"':''}></div>`;}
function ownSummary(source=ownState().source,exclude){const s=ownRoutes.find(s=>s.id===source),f=ownFunds(source,exclude);return `<section class="panel"><h2>${pl('Средства источника','Source funds')}</h2><p>${s.id} · ${s.asset} · ${s.network}</p><p class="full-address">${s.address}</p><dl class="own-breakdown">${[['Подтверждённый остаток','Confirmed balance',f.balance],['Обязательства','Liabilities',f.obligations],['Другие резервы','Other reserves',f.reserves],['Минимальный остаток','Minimum balance',f.floor],['Выводы в ожидании, включая этот','Pending withdrawals, including this',ownFunds(source).held],['Свободно после резервирования','Available after reservations',ownFunds(source).available]].map(([r,e,n])=>`<div><dt>${pl(r,e)}</dt><dd>${ownMoney(n,s.asset)}</dd></div>`).join('')}</dl><p>${pl('Комиссия сети отдельно','Network fee separately')}: ${s.fee} ${s.gas}. ${pl('Доступно для комиссии','Available for fees')}: ${ownGasFree(source)} ${s.gas}.</p><small>${pl('Учебные остатки. Категории не пересекаются; 0 в минимальном остатке не освобождает обязательства и резервы.','Synthetic balances. Categories do not overlap; a zero floor does not release liabilities or reserves.')}</small></section>`;}
function ownSafeReconciliation(){return typeof finance!=='undefined'&&finance.view==='own'&&finance.own?.screen==='review'&&finance.own?.records.some(p=>p.id===finance.own.current&&p.status==='unknown');}
function ownReconciliationLink(){return (typeof depositAllowed==='function'&&depositAllowed()?`<button type="button" class="btn" data-deposit="open">${pl('Проверить входящие пополнения','Check incoming funding')}</button>`:'')+(financeAccess().read&&finance.own?.records.some(p=>p.status==='unknown')?ownButton('Проверить неизвестный вывод средств','Check unknown own-funds withdrawal','open'):'');}
function ownWithdrawalPage(){const x=ownState(),s=ownSource(),p=ownCurrent(),pending=x.records.some(p=>!ownTerminal(p)&&p.id!==x.current);let body='';
 if(x.screen==='settings'){const d=x.floorDraft;body=`<section class="panel"><h2>${pl('Минимальный остаток','Minimum balance')}</h2><p>${s.id} · ${s.asset} · ${s.network}</p><p>${pl('Это настраиваемый запас сверх обязательств и резервов. Изменение подтверждают два владельца. Можно установить 0.','A configurable buffer above liabilities and reserves. Changes require two owners. Zero is allowed.')}</p>${ownInput('floorInput','Новый остаток','New minimum balance',x.floorInput??String(x.floors[s.id].value/1e6),'number')}${ownInput('floorReason','Причина изменения','Reason for change',x.floorReason)}<div class="actions">${ownButton('Проверить изменение','Review change','floor-review')}${ownButton('Назад к выводу','Back to withdrawal','back')}</div>${d?`<p>${pl('Проверяем','Reviewing')}: ${ownMoney(d.units,s.asset)} · v${d.version} · ${escape(d.reason)}</p><p>${pl('Подтверждения','Approvals')}: ${d.approvals.length}/2</p><div class="actions">${ownButton('Проверить личность · демо','Verify identity · demo','floor-proof')}${ownButton('Подтвердить остаток','Approve minimum balance','floor-approve')}${ownButton('Войти другим владельцем','Sign in as another owner','handoff')}</div>`:''}</section>`;
 }else if(x.screen==='review'&&p&&p.status!=='draft'){const src=ownRoutes.find(s=>s.id===p.source),done=ownTerminal(p);body=`<section class="panel"><h2>${p.id} · ${['waiting','approved'].includes(p.status)&&ownApprovals(p).length===0?pl('Согласия истекли · подтвердите заново','Approvals expired · approve again'):pl(...ownStates[p.status])}</h2><dl class="own-breakdown"><div><dt>${pl('Получателю','To recipient')}</dt><dd>${ownMoney(p.units,src.asset)}</dd></div><div><dt>${pl('Сеть','Network')}</dt><dd>${src.network}</dd></div></dl><p>${pl('Полный адрес получателя','Complete recipient address')}</p><p class="full-address">${escape(p.address)}</p><p>${pl('Списание токена','Token debit')}: ${ownMoney(p.units,src.asset)} · ${pl('Комиссия сети отдельно','Separate network fee')}: ${p.fee} ${src.gas}</p><p>${escape(p.reason)} · v${p.version}</p><p class="muted">${pl('Согласия действуют 5 минут до отправки; после истечения подтвердите заново.','Approvals expire after 5 minutes before submission; approve again if expired.')}</p><p>${pl('Подтверждения двух владельцев','Two-owner approvals')}: ${ownDisplayApprovals(p).length}/2</p><ul>${ownDisplayApprovals(p).map(a=>`<li>${a.id} · ${pl('подтверждено','approved')}</li>`).join('')}</ul><div class="actions">${!done&&p.status!=='unknown'?ownButton('Проверить личность · демо','Verify identity · demo','proof')+ownButton('Подтвердить вывод','Approve withdrawal','approve',true)+ownButton('Войти другим владельцем','Sign in as another owner','handoff')+ownButton('Изменить реквизиты','Edit transfer','edit')+ownButton('Отменить до отправки','Cancel before submission','cancel'):''}${p.status==='approved'?ownButton('Отправить · учебный перевод','Submit · synthetic transfer','send',true):''}${p.status==='unknown'?ownButton('Сверить исходный перевод','Reconcile original transfer','reconcile',true):''}${done?ownButton('Новый вывод','New withdrawal','new'):''}</div><p>${p.status==='unknown'?pl('Ответ не подтверждён. Сумма и комиссия зарезервированы. Не отправляйте перевод повторно.','Outcome unconfirmed. Amount and fee remain reserved. Do not resend the transfer.'):pl('Новый адрес не требует ожидания 24 часа. Два владельца проверяют точные реквизиты.','New addresses have no 24-hour delay. Both owners review the exact transfer details.')}</p>${p.external?`<p>${pl('Подтверждающие данные','Evidence')}: ${p.external}</p>`:''}</section>`+ownSummary(p.source,p.id);
 }else{body=`<div class="support-layout"><form class="panel" id="own-form"><h2>${pl('Вывести собственные средства','Withdraw own funds')}</h2>${supportSelect('own-source',pl('Источник, валюта и сеть','Source, asset and network'),ownRoutes.map(s=>[s.id,s.asset+' · '+s.network+' · '+s.id]),x.source)}${ownInput('address','Полный адрес получателя','Complete recipient address',x.address)}<p id="own-address-preview" class="full-address">${escape(x.address)}</p><p class="muted">${pl('Любой внешний адрес выбранной сети. Проверка формата не подтверждает владельца адреса или возможность зачисления.','Any external address in the selected network. Format validation does not verify ownership or deposit support.')}</p>${ownInput('amount','Сумма получателю, '+s.asset,'Recipient amount, '+s.asset,x.amount,'number')}${ownInput('reason','Назначение перевода','Transfer purpose',x.reason)}<label class="own-ack"><input type="checkbox" id="own-ack" ${x.ack?'checked':''}>${pl('Я сверил полный адрес, сеть и валюту с получателем','I checked the complete address, network and asset with the recipient')}</label><div class="actions"><button class="btn primary" type="submit" ${pending?'disabled':''}>${pl('Проверить вывод','Review withdrawal')}</button>${ownButton('Настроить минимальный остаток','Set minimum balance','settings')}</div><p>${pl('После проверки нужны два владельца. Обязательной задержки нового адреса нет.','Two owners are required after review. No mandatory delay for a new address.')}</p></form>${ownSummary()}</div>`;}
 return `<div class="actions">${typeof depositAllowed==='function'&&depositAllowed()?`<button type="button" class="btn primary" data-deposit="open">${pl('Пополнить извне','Add funds from outside')}</button>`:''}${ownButton('Новый вывод','New withdrawal','new')}${ownButton('Минимальный остаток','Minimum balance','settings')}</div><p>${pl('Учебные собственные кошельки Shadow. Не деньги клиентов, не партнёрские выплаты и не кошельки площадок. Реальных переводов нет.','Synthetic Shadow service wallets. Not client funds, partner payouts or venue wallets. No real transfers.')}</p>${x.notice?`<p class="support-notice" role="status">${pl(...x.notice)}</p>`:''}${ownBlocked()?`<p role="alert">${pl('Денежные действия заблокированы. Сверка исходной операции остаётся безопасной проверкой.','Money actions blocked. Original-operation reconciliation remains a safe check.')}</p>`:''}${body}<section class="panel"><h2>${pl('История выводов','Withdrawal history')}</h2>${x.records.length?financeTable([pl('Операция','Operation'),pl('Сумма','Amount'),pl('Сеть','Network'),pl('Состояние','Status')],x.records.map(p=>{const s=ownRoutes.find(s=>s.id===p.source);return `<tr><td><button class="btn" data-own-record="${p.id}">${p.id}</button></td><td>${ownMoney(p.units,s.asset)}</td><td>${s.network}</td><td>${pl(...ownStates[p.status])}</td></tr>`;})):`<p>${pl('Выводов пока нет','No withdrawals yet')}</p>`}</section><details class="panel"><summary>${pl('Учебная проверка исходов и запретов','Synthetic outcomes and restrictions')}</summary>${supportSelect('own-outcome',pl('Данные для сверки','Reconciliation evidence'),[['unknown',pl('Данных недостаточно','Insufficient evidence')],['success',pl('Исходный перевод подтверждён','Original transfer confirmed')],['failure',pl('Окончательный отказ без списания','Final failure without debit')]],x.outcome)}${supportSelect('own-block',pl('Денежный запрет · демо','Money restriction · demo'),[['none',pl('Нет','None')],['global',pl('Все денежные действия','All money actions')],['source',pl('Источник','Source')],['address',pl('Получатель','Recipient')]],x.block)}<p>${pl('Суммы, комиссии и подтверждения вымышлены. Проверка ключа моделируется; прототип не запрашивает ключи.','Amounts, fees and evidence are synthetic. Key verification is simulated; no keys are requested.')}</p></details>`;
}
document.addEventListener('click',e=>{const record=e.target.closest('[data-own-record]');if(record&&financeAccess().read){ownState().current=record.dataset.ownRecord;ownState().screen='review';render();return;}const n=e.target.closest('[data-own]');if(n&&!n.disabled){ownAction(n.dataset.own);render();}});
document.addEventListener('input',e=>{if(!financeAccess().read||!e.target.dataset.ownField)return;const x=ownState(),key=e.target.dataset.ownField;x[key]=e.target.value;if(key==='address'){const preview=document.querySelector('#own-address-preview');if(preview)preview.textContent=x.address;}if(key.startsWith('floor')){x.floorDraft=null;finance.proof=null;}});
document.addEventListener('change',e=>{if(!financeAccess().read)return;const x=ownState();if(e.target.id==='own-source'){x.source=e.target.value;x.address='';x.ack=false;x.floorDraft=null;render();}if(e.target.id==='own-ack')x.ack=e.target.checked;if(e.target.id==='own-outcome')x.outcome=e.target.value;if(e.target.id==='own-block'){x.block=e.target.value;finance.proof=null;for(const p of x.records.filter(p=>['review','waiting','approved'].includes(p.status))){p.approvals=[];p.status='review';}render();}});
document.addEventListener('submit',e=>{if(e.target.id==='own-form'){e.preventDefault();ownAction('review');render();}});
